(776, 65, 'trnsmp_frmt_gen_ht_msg', '', '', 'message', 0, 'text', 604, NULL, '            <h2>Settings for the general size of this Transition</h2>\n            <h4>Padding adds to height and MUST be set to more than \'0\'  if no text in this section.</h4>\n        ', 0, 0, '', '', '', '', '', '', '', '', '', '', 0, 0, 0, 'trnsmp_frmt_gen_ht_row', -1, '', 0, 0, 80, 0, 0, 0, 0, 0, '', '', 0, '<cms:editable\r\ntype=\'message\'\r\nname=\'trnsmp_frmt_gen_ht_msg\'\r\norder=\'604\'\r\ngroup=\'trnsmp_frmt_gen_ht_row\'/>', '', NULL, 1, '', ''),
(777, 65, 'trnsmp_py_ht', 'Top and Bottom Padding', 'space from the Y edges', 'dropdown', 0, 'text', 607, NULL, '', 0, 0, '', '', '', '', '0|2|3|5|6|8|10|11', '', '', '', '', '', 0, 0, 0, 'trnsmp_frmt_gen_ht_row', -1, '', 0, 0, 80, 0, 0, 0, 0, 0, '', '', 0, '<cms:editable\r\ntype=\'dropdown\'\r\nname=\'trnsmp_py_ht\'\r\nlabel=\'Top and Bottom Padding\'\r\ndesc=\'space from the Y edges\'\r\nopt_values=\'0|2|3|5|6|8|10|11\'\r\nclass=\'col-md-4\'\r\norder=\'607\'\r\ngroup=\'trnsmp_frmt_gen_ht_row\'/>', '', NULL, 1, 'col-md-4', ''),
(778, 65, 'trnsmp_txtbx_txt_opt', 'Remove Text', 'if checked, padding MUST be more than 0', 'checkbox', 0, 'text', 608, NULL, '', 0, 0, '', '', '', '', 'Remove Text=1', '', '', '', '', '', 0, 0, 0, 'trnsmp_frmt_gen_ht_row', -1, '', 0, 0, 80, 0, 0, 0, 0, 0, '', '', 0, '<cms:editable\r\ntype=\'checkbox\'\r\nname=\'trnsmp_txtbx_txt_opt\'\r\nlabel=\'Remove Text\'\r\ndesc=\'if checked, padding MUST be more than 0\'\r\nopt_values=\'Remove Text=1\'\r\nclass=\'col-md-4\'\r\norder=\'608\'\r\ngroup=\'trnsmp_frmt_gen_ht_row\'/>', '', NULL, 1, 'col-md-4', ''),
