(780, 65, 'trnsmp_form_gen_clr_msg', '', '', 'message', 0, 'text', 611, NULL, '            <hr><br>\n            <h2>Optional background color and overlay shading</h2>\n            <h4>All Solid Colors will cover image. \"Custom Colors\" transparency reveal images and add colored highlights.</h4>\n            <p>Choosing \'Custom\' option will open up additional options below where transparency can be set.</p>\n        ', 0, 0, '', '', '', '', '', '', '', '', '', '', 0, 0, 0, 'trnsmp_frmt_gen_clr_row', -1, '', 0, 0, 80, 0, 0, 0, 0, 0, '', '', 0, '<cms:editable\r\ntype=\'message\'\r\nname=\'trnsmp_form_gen_clr_msg\'\r\norder=\'611\'\r\ngroup=\'trnsmp_frmt_gen_clr_row\'/>', '', NULL, 1, '', ''),
(781, 65, 'trnsmp_bg_clr_opt', 'Optional Background Color', '', 'dropdown', 0, 'text', 612, NULL, '', 0, 0, '', '', '', '', 'dropdowns/all-colors.htm', '', '', '', '', '', 0, 0, 0, 'trnsmp_frmt_gen_clr_row', -1, '', 0, 0, 80, 0, 0, 0, 0, 0, '', '', 0, '<cms:editable\r\ntype=\'dropdown\'\r\nname=\'trnsmp_bg_clr_opt\'\r\nlabel=\'Optional Background Color\'\r\ndesc=\'\'\r\nopt_values=\'dropdowns/all-colors.htm\'\r\ndynamic=\'opt_values\'\r\nclass=\'col-md-4\'\r\norder=\'612\'\r\ngroup=\'trnsmp_frmt_gen_clr_row\'/>', 'opt_values', NULL, 1, 'col-md-4', ''),
