(784, 65, 'trnsmp_gen_xtr_scrl_msg', '', '', 'message', 0, 'text', 617, NULL, '            <hr><br>\n            <h2>Scrolling Effect</h2><h4>Scrolling Effects are a 3D effect when user scrolls. Negative numbers make it appear the image is behind the page, positive numbers make it appear it is on top.</h4><p>Adds attratction!</p>\n        ', 0, 0, '', '', '', '', '', '', '', '', '', '', 0, 0, 0, 'trnsmp_gen_xt_row', -1, '', 0, 0, 80, 0, 0, 0, 0, 0, '', '', 0, '<cms:editable\r\ntype=\'message\'\r\nname=\'trnsmp_gen_xtr_scrl_msg\'\r\norder=\'617\'\r\ngroup=\'trnsmp_gen_xt_row\'/>', '', NULL, 1, '', ''),
(785, 65, 'trnsmp_bg_scrl_spd', 'Add Page Scrolling Effect', '', 'dropdown', 0, 'text', 618, NULL, '', 0, 0, '', '', '', '', 'No Scrolling Effect=0|-6|-5|-4|-3|-2|-1|1|2|3|4|5|6', '', '', '', '', '', 0, 0, 0, 'trnsmp_gen_xt_row', -1, '', 0, 0, 80, 0, 0, 0, 0, 0, '', '', 0, '<cms:editable\r\ntype=\'dropdown\'\r\nname=\'trnsmp_bg_scrl_spd\'\r\nlabel=\'Add Page Scrolling Effect\'\r\ndesc=\'\'\r\nopt_values=\'No Scrolling Effect=0|-6|-5|-4|-3|-2|-1|1|2|3|4|5|6\'\r\nclass=\'col-md-4\'\r\norder=\'618\'\r\ngroup=\'trnsmp_gen_xt_row\'/>', '', NULL, 1, 'col-md-4', ''),
